// Nilad F4 — keep low-stock products from the Woo /products list, dedupe against static data.
// Requires env: LOW_STOCK_QTY. Input: single item { json: [ ...products ] } (Woo REST array).
// Output: one item per hit { productId, name, stock, qty }, or [{ json: { none: true } }].
const threshold = Number($env.LOW_STOCK_QTY);
const raw = $input.first().json;
const products = Array.isArray(raw) ? raw : [];
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const hits = [];
for (const p of products) {
  if (!p || p.manage_stock !== true) continue;
  const stock = p.stock_quantity;
  if (typeof stock !== 'number' || !Number.isFinite(stock)) continue;
  if (!(stock <= threshold)) continue;
  const key = 'f4:' + p.id + ':' + stock;
  if (sd.keys.includes(key)) continue;
  hits.push({ json: { productId: p.id, name: p.name, stock, qty: stock } });
}
return hits.length ? hits : [{ json: { none: true } }];

// Nilad F4 — build ONE Arabic Telegram text (HTML-escaped) listing every low-stock hit.
// Input: all 'Collect low stock' items { productId, name, stock, qty }.
// Output: single item { tgText, keys } (keys = f4:<id>:<qty> for idempotency).
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const hits = $input.all().map((i) => i.json);
const lines = hits.map((h) => '• ' + esc(h.name) + ' — المتبقي: ' + esc(h.qty));
const keys = hits.map((h) => 'f4:' + h.productId + ':' + h.qty);
const tgText = ['تنبيه: مخزون منخفض'].concat(lines).join('\n');
return [{ json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '', tgText, keys } }];

// Nilad F4 — persist alerted idempotency keys in workflow static data (cap 500). Passthrough.
const sd = $getWorkflowStaticData('global');
sd.keys = Array.isArray(sd.keys) ? sd.keys : [];
const json = $input.first().json;
const keys = Array.isArray(json.keys) ? json.keys : [];
for (const k of keys) {
  if (!sd.keys.includes(k)) sd.keys.push(k);
}
if (sd.keys.length > 500) sd.keys.splice(0, sd.keys.length - 500);
return [{ json: {
    // n8n 2.41 blocks $env in node expressions (Code nodes may read it), so
    // the Telegram HTTP node gets its credentials from this item instead.
    tgToken: $env.TELEGRAM_BOT_TOKEN || '',
    tgChatId: $env.TELEGRAM_CHAT_ID || '', ...json } }];
